    levels = max((len(line)-1 for line in lines), default=0)
    for column in range(levels):
        start = 0
        while start < len(lines):
            if len(lines[start]) <= column+1:
                start += 1
                continue
            end = start
            maximum = width
            while end < len(lines) and len(lines[end]) > column+1:
                maximum = max(maximum, widths[end][column])
                end += 1
            for i in range(start, end):
                pads[i][column] = maximum + pad - widths[i][column]
            start = end
    output = []
    for cells, spaces in zip(lines, pads):
        output.append(b''.join(cell + (b' ' * spaces[i] if i < len(spaces) else b'') for i, cell in enumerate(cells)))
    return b'\n'.join(output)
