import math
import re
from collections import Counter
from decimal import Decimal

INTEGER = re.compile(rb'[+-]?[0-9]+\Z')
FLOAT = re.compile(rb'[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)\Z', re.I)


def as_number(value):
    if INTEGER.fullmatch(value):
        n = int(value)
        if -(1 << 63) <= n < (1 << 63):
            return 'Integer', n
    if FLOAT.fullmatch(value):
        try:
            return 'Float', float(value)
        except (ValueError, OverflowError):
            pass
    return None, None


def float_string(value):
    if math.isnan(value):
        return 'NaN'
    if math.isinf(value):
        return '-inf' if value < 0 else 'inf'
    s = repr(value)
    if 'e' in s or 'E' in s:
        return format(Decimal(s), 'f')
    return s[:-2] if s.endswith('.0') else s


def numeric_string(value):
    return float_string(value) if isinstance(value, float) else str(value)


def wrap_int(n):
    return (n + (1 << 63)) % (1 << 64) - (1 << 63)


class ColumnStats:
    def __init__(self, median=False, mode=False, cardinality=False, nulls=False):
        self.kind = 'NULL'
        self.sum = 0
        self.minimum = self.maximum = None
        self.byte_min = self.byte_max = None
        self.min_length = self.max_length = None
        self.n = 0
        self.mean = 0.0
        self.m2 = 0.0
        self.values = [] if median else None
        self.counts = Counter() if mode or cardinality else None
        self.nulls = nulls

    def add_population(self, x):
        self.n += 1
        delta = x - self.mean
        self.mean += delta / self.n
        self.m2 += delta * (x - self.mean)

    def add(self, value):
        size = len(value)
        if self.min_length is None:
            self.min_length = self.max_length = size
        else:
            self.min_length = min(self.min_length, size)
            self.max_length = max(self.max_length, size)
