"""Command-line parsing and dispatch without third-party dependencies."""
import importlib.resources
import json
import os
import sys
from .core import ToolError, os_message
from .selection import unsigned

COMMANDS = ['cat', 'count', 'fixlengths', 'flatten', 'fmt', 'frequency',
            'headers', 'help', 'index', 'input', 'join', 'partition', 'reverse',
            'sample', 'search', 'select', 'slice', 'sort', 'split', 'stats', 'table']

# name, abbreviation, value kind, default
COMMON = [('help', 'h', 'bool', False), ('delimiter', 'd', 'char', None)]
OUTPUT = ('output', 'o', 'str', None)
NO_HEADERS = ('no-headers', 'n', 'bool', False)
SELECT = ('select', 's', 'str', None)
JOBS = ('jobs', 'j', 'uint', 0)
SCHEMA = {
    'cat': [OUTPUT, NO_HEADERS, ('pad', 'p', 'bool', False)],
    'count': [NO_HEADERS],
    'fixlengths': [OUTPUT, ('length', 'l', 'uint', None)],
    'flatten': [NO_HEADERS, ('condense', 'c', 'uint', None), ('separator', 's', 'str', '#')],
    'fmt': [OUTPUT, ('out-delimiter', 't', 'char', 44), ('crlf', '', 'bool', False), ('ascii', '', 'bool', False), ('quote', '', 'char', 34), ('quote-always', '', 'bool', False), ('escape', '', 'char', None)],
    'frequency': [OUTPUT, NO_HEADERS, SELECT, ('limit', 'l', 'uint', 10), ('asc', 'a', 'bool', False), ('no-nulls', '', 'bool', False), JOBS],
    'headers': [('just-names', 'j', 'bool', False), ('intersect', '', 'bool', False)],
    'index': [OUTPUT],
    'input': [OUTPUT, ('quote', '', 'char', 34), ('escape', '', 'char', None), ('no-quoting', '', 'bool', False)],
    'join': [OUTPUT, NO_HEADERS] + [(x, '', 'bool', False) for x in ('no-case', 'left', 'right', 'full', 'cross', 'nulls')],
    'partition': [NO_HEADERS, ('filename', '', 'str', '{}.csv'), ('prefix-length', 'p', 'uint', None), ('drop', '', 'bool', False)],
    'reverse': [OUTPUT, NO_HEADERS],
    'sample': [OUTPUT, NO_HEADERS, ('seed', '', 'uint', None)],
    'search': [OUTPUT, NO_HEADERS, SELECT, ('ignore-case', 'i', 'bool', False), ('invert-match', 'v', 'bool', False)],
    'select': [OUTPUT, NO_HEADERS],
    'slice': [OUTPUT, NO_HEADERS] + [(x, a, 'uint', None) for x,a in [('start','s'), ('end','e'), ('len','l'), ('index','i')]],
    'sort': [OUTPUT, NO_HEADERS, SELECT, ('numeric', 'N', 'bool', False), ('reverse', 'R', 'bool', False)],
    'split': [NO_HEADERS, ('size', 's', 'uint', 500), JOBS, ('filename', '', 'str', '{}.csv')],
    'stats': [OUTPUT, NO_HEADERS, SELECT] + [(x, '', 'bool', False) for x in ('everything','mode','cardinality','median','nulls')] + [JOBS],
    'table': [OUTPUT, ('width', 'w', 'uint', 2), ('pad', 'p', 'uint', 2), ('condense', 'c', 'uint', None)],
}


def manual(command):
    return importlib.resources.files('csvtool').joinpath('manual', command + '.txt').read_text()


def usage(command):
    s = manual(command)
    i = s.index('Usage:')
    return s[i:].split('\n\n')[0].rstrip() + '\n'


def argument_error(message, command):
    raise ToolError(message + '\n\n' + usage(command).rstrip('\n'))


def convert(value, kind, name):
    if kind == 'uint':
        result = unsigned(value)
        if result is None:
            raise ToolError("Could not deserialize '{}' to u64 for '{}'.".format(value, name))
        return result
    if kind == 'char':
        if value == r'\t':
            return 9
        if len(value) == 1 and ord(value) < 128:
            return ord(value)
        raise ToolError("Could not convert '{}' to a single ASCII character.".format(value))
    return value


def parse(command, args):
    specs = COMMON + SCHEMA[command]
    by_long = {x[0]: x for x in specs}
    by_short = {x[1]: x for x in specs if x[1]}
    found = {}
    duplicate = False
    positionals = []
    end_options = False
    i = 0
    while i < len(args):
        token = args[i]
        i += 1
        if end_options or token == '-' or not token.startswith('-'):
            positionals.append(token)
            continue
        if token == '--':
            end_options = True
            continue
        pending = []
        if token.startswith('--'):
            name, eq, value = token[2:].partition('=')
            if name not in by_long:
                argument_error("Unknown flag: '--{}'".format(name), command)
            spec = by_long[name]
            if spec[2] == 'bool':
                if eq:
                    argument_error("Flag '--{}' cannot have an argument, but found '{}'.".format(name, value), command)
                value = True
            elif not eq:
                if i == len(args):
                    argument_error("Expected argument for flag '--{}' but reached end of arguments.".format(name), command)
                value = args[i]
                i += 1
            pending.append((spec, value))
        else:
            j = 1
            while j < len(token):
                short = token[j]
                j += 1
                if short not in by_short:
                    argument_error("Unknown flag: '-{}'".format(short), command)
                spec = by_short[short]
                if spec[2] == 'bool':
                    value = True
                elif j < len(token):
                    value = token[j:]
                    j = len(token)
                else:
                    if i == len(args):
                        argument_error("Expected argument for flag '--{}' but reached end of arguments.".format(spec[0]), command)
                    value = args[i]
                    i += 1
                pending.append((spec, value))
        for spec, value in pending:
            if spec[0] in found:
                duplicate = True
            found[spec[0]] = value
    if found.get('help'):
        sys.stdout.write(manual(command))
        return None, None
    if duplicate:
        argument_error('Invalid arguments.', command)
    n = len(positionals)
    if command == 'cat':
        valid = n >= 1 and positionals[0] in ('rows', 'columns')
    elif command == 'join':
        valid = n == 4
    elif command == 'partition':
        valid = 2 <= n <= 3
    elif command in ('sample', 'search', 'select', 'split'):
        valid = 1 <= n <= 2
    elif command == 'index':
        valid = n == 1
    elif command == 'headers':
        valid = True
    else:
        valid = n <= 1
    if not valid:
        argument_error('Invalid arguments.', command)
    opts = {}
    for name, short, kind, default in specs:
        if name not in found:
            opts[name] = default
        else:
            opts[name] = found[name] if kind == 'bool' else convert(found[name], kind, '--'+name)
    if command == 'sample':
        positionals[0] = convert(positionals[0], 'uint', '<sample-size>')
    return opts, positionals


def run(args):
    if not args:
        block = manual('main').split('Commands:\n', 1)[1].rstrip('\n')
        sys.stderr.write('xsv is a suite of CSV command line utilities.\n\nPlease choose one of the following commands:\n' + block + '\n\n')
        return
    command = args[0]
    if command.startswith('-') and command != '-':
        known = ('--help', '-h', '--list', '--version')
        for flag in args:
            if flag.startswith('-') and flag not in known:
                argument_error("Unknown flag: '{}'".format(flag), 'main')
        if len(args) != 1:
            argument_error('Invalid arguments.', 'main')
        if command in ('--help', '-h'):
            sys.stdout.write(manual('main'))
        elif command == '--version':
            sys.stdout.write('0.13.0\n')
        else:
            block = manual('main').split('Commands:\n', 1)[1].rstrip('\n')
            sys.stdout.write('Installed commands:\n' + block + '\n\n')
        return
    if command.lower() != command:
        raise ToolError("xsv expects commands in lowercase. Did you mean '{}'?".format(command.lower()))
    if command not in COMMANDS:
        raise ToolError("Could not match '{}' with any of the allowed variants: {}".format(command, json.dumps(COMMANDS)))
    if command == 'help':
        sys.stdout.write('\n' + manual('main').rstrip('\n') + '\n\n')
        return
    opts, positional = parse(command, args[1:])
    if opts is not None:
        from .commands import execute
        execute(command, opts, positional)


def main():
    code = 0
    try:
        run(sys.argv[1:])
    except ToolError as e:
        sys.stderr.write(str(e) + '\n')
        code = 1
    except BrokenPipeError:
        code = 0
    except OSError as e:
        sys.stderr.write(os_message(e) + '\n')
        code = 1
    try:
        sys.stdout.flush()
    except BrokenPipeError:
        sys.stdout = open(os.devnull, 'w')
    if code:
        raise SystemExit(code)
