"""Condensed fields and an elastic-tabstop text formatter."""
import unicodedata


def condense(value, limit):
    if limit is None:
        return value
    try:
        text = value.decode('utf-8')
        return (text[:limit] + ('...' if len(text) > limit else '')).encode('utf-8')
    except UnicodeDecodeError:
        return value[:limit] + (b'...' if len(value) > limit else b'')


def char_width(ch):
    code = ord(ch)
    if 0xDC80 <= code <= 0xDCFF:
