    if ch == '\x00' or unicodedata.category(ch) in ('Mn', 'Me', 'Cf'):
        return 0
    if unicodedata.category(ch) == 'Cc':
        return 0
    if unicodedata.east_asian_width(ch) in ('W', 'F'):
        return 2
    return 1


def display_width(value):
    return sum(char_width(ch) for ch in value.decode('utf-8', 'surrogateescape'))


def elastic_tabs(data, width=2, pad=2):
    """Align each contiguous run of cells with a shared tabstop.

    Lines that end before a tabstop separate the independent alignment blocks.
