def manual(command):
    return importlib.resources.files('csvtool').joinpath('manual', command + '.txt').read_text()


def usage(command):
    s = manual(command)
    i = s.index('Usage:')
    return s[i:].split('\n\n')[0].rstrip() + '\n'


def argument_error(message, command):
    raise ToolError(message + '\n\n' + usage(command).rstrip('\n'))


def convert(value, kind, name):
    if kind == 'uint':
        result = unsigned(value)
        if result is None:
            raise ToolError("Could not deserialize '{}' to u64 for '{}'.".format(value, name))
        return result
    if kind == 'char':
        if value == r'\t':
            return 9
        if len(value) == 1 and ord(value) < 128:
            return ord(value)
        raise ToolError("Could not convert '{}' to a single ASCII character.".format(value))
    return value


def parse(command, args):
    specs = COMMON + SCHEMA[command]
    by_long = {x[0]: x for x in specs}
    by_short = {x[1]: x for x in specs if x[1]}
    found = {}
    duplicate = False
    positionals = []
    end_options = False
    i = 0
    while i < len(args):
        token = args[i]
        i += 1
        if end_options or token == '-' or not token.startswith('-'):
            positionals.append(token)
            continue
        if token == '--':
            end_options = True
            continue
        pending = []
        if token.startswith('--'):
            name, eq, value = token[2:].partition('=')
            if name not in by_long:
                argument_error("Unknown flag: '--{}'".format(name), command)
            spec = by_long[name]
            if spec[2] == 'bool':
                if eq:
                    argument_error("Flag '--{}' cannot have an argument, but found '{}'.".format(name, value), command)
                value = True
            elif not eq:
                if i == len(args):
                    argument_error("Expected argument for flag '--{}' but reached end of arguments.".format(name), command)
                value = args[i]
                i += 1
            pending.append((spec, value))
        else:
            j = 1
            while j < len(token):
                short = token[j]
                j += 1
                if short not in by_short:
                    argument_error("Unknown flag: '-{}'".format(short), command)
                spec = by_short[short]
                if spec[2] == 'bool':
                    value = True
                elif j < len(token):
                    value = token[j:]
                    j = len(token)
                else:
                    if i == len(args):
                        argument_error("Expected argument for flag '--{}' but reached end of arguments.".format(spec[0]), command)
                    value = args[i]
                    i += 1
                pending.append((spec, value))
        for spec, value in pending:
            if spec[0] in found:
                duplicate = True
            found[spec[0]] = value
    if found.get('help'):
        sys.stdout.write(manual(command))
        return None, None
    if duplicate:
        argument_error('Invalid arguments.', command)
    n = len(positionals)
    if command == 'cat':
        valid = n >= 1 and positionals[0] in ('rows', 'columns')
    elif command == 'join':
        valid = n == 4
    elif command == 'partition':
        valid = 2 <= n <= 3
    elif command in ('sample', 'search', 'select', 'split'):
        valid = 1 <= n <= 2
    elif command == 'index':
        valid = n == 1
    elif command == 'headers':
        valid = True
    else:
        valid = n <= 1
    if not valid:
        argument_error('Invalid arguments.', command)
    opts = {}
