"""The regular expression interface used by CSV search."""
import re
from .core import ToolError


def syntax_error(pattern, position, length, message):
    border = '~' * 79
    pointer = ' ' * max(position, 0) + '^' * max(length, 1)
    detail = 'regex parse error:\n    {}\n    {}\nerror: {}'.format(pattern, pointer, message)
    raise ToolError('Syntax(\n{}\n{}\n{}\n)'.format(border, detail, border))


def compile_pattern(pattern, ignore_case=False):
    displayed = ('(?i)' if ignore_case else '') + pattern
    for m in re.finditer(r'\(\?(?:[=!]|<[=!])', displayed):
        syntax_error(displayed, m.start(), len(m.group()), 'look-around, including look-ahead and look-behind, is not supported')
    m = re.search(r'(?<!\\)\\[1-9]', displayed)
    if m:
        syntax_error(displayed, m.start(), 2, 'backreferences are not supported')
    transformed = displayed
    replacements = {
        '[[:digit:]]': '[0-9]', '[[:alpha:]]': '[A-Za-z]',
        '[[:alnum:]]': '[A-Za-z0-9]', '[[:space:]]': '[\\t\\n\\v\\f\\r ]',
        '[[:lower:]]': '[a-z]', '[[:upper:]]': '[A-Z]',
        '[[:word:]]': '[A-Za-z0-9_]', '[[:xdigit:]]': '[A-Fa-f0-9]',
        '[[:blank:]]': '[ \\t]', '[[:ascii:]]': '[\\x00-\\x7f]',
        r'\p{Greek}': '[\u0370-\u03ff\u1f00-\u1fff]',
        r'\p{Cyrillic}': '[\u0400-\u052f]',
        r'\p{Han}': '[\u3400-\u9fff\U00020000-\U0002ffff]',
        r'\p{ASCII}': '[\\x00-\\x7f]',
        r'\p{L}': '[^\\W\\d_]', r'\pL': '[^\\W\\d_]',
        r'\p{Letter}': '[^\\W\\d_]', r'\p{N}': r'\d',
        r'\p{Nd}': r'\d', r'\p{Number}': r'\d',
        r'\p{White_Space}': r'\s', r'\z': r'\Z',
    }
    for old, new in replacements.items():
        transformed = transformed.replace(old, new)
    transformed = re.sub(r'\\x\{([0-9a-fA-F]+)\}', lambda m: chr(int(m[1],16)), transformed)
    # Unicode is the default in the byte-search interface. Explicitly disabling
    # it is useful for ASCII classes and arbitrary-byte searches.
    raw_mode = '(?-u' in transformed
    transformed = transformed.replace('(?-u:', '(?a:').replace('(?-u)', '(?a)')
    transformed = re.sub(r'\(\?<([A-Za-z_][A-Za-z_0-9]*)>', r'(?P<\1>', transformed)
    try:
        compiled = re.compile(transformed)
    except re.error as e:
        pos = e.pos or 0
        msg = e.msg
        length = 1
        if 'unterminated character set' in msg:
            msg = 'unclosed character class'
        elif 'unterminated subpattern' in msg:
            msg = 'unclosed group'
        elif 'unbalanced parenthesis' in msg:
            msg = 'unopened group'
        elif 'nothing to repeat' in msg:
            msg = 'repetition operator missing expression'
        elif 'bad escape' in msg:
            msg = 'unrecognized escape sequence'
            length = 2
        elif 'bad character range' in msg:
            msg = 'invalid character class range, the start must be <= the end'
            length = 3
        syntax_error(displayed, pos, length, msg)
    def matches(value):
        text = value.decode('latin-1') if raw_mode else value.decode('utf-8', 'surrogateescape')
        for match in compiled.finditer(text):
            if raw_mode or not any(0xdc80 <= ord(c) <= 0xdcff for c in match.group()):
                return True
        return False
    return matches
