"""CSV operations composed from the byte parser and common selection grammar."""
import functools
import io
import math
import os
import random
import struct
import sys
from collections import Counter, defaultdict

from .core import (Reader, Writer, ToolError, csv_record, read_bytes,
                   open_output, get_index, make_directory, trim_bytes)
from .selection import Selection
from .formatting import condense, elastic_tabs
from .statistics import ColumnStats, as_number
from .regex_support import compile_pattern


def reader(options, path=None, **kwargs):
    return Reader(path, options.get('delimiter'), options.get('no-headers', False), **kwargs)


def writer(options, **kwargs):
    return Writer(options.get('output'), **kwargs)


def select_columns(options, source, text=None):
    return Selection(options.get('select') if text is None else text).resolve(source.header, source.no_headers)


def write_selected(w, row, columns):
    w.write(row[i] for i in columns)


def data_path(args):
    return args[-1] if args else None


def count(options, args):
    path = data_path(args)
    index = get_index(path)
    if index is not None:
        n = index[0]
        if not options['no-headers']:
            n = max(n-1, 0)
    else:
        source = reader(options, path)
        n = sum(1 for row in source.rows())
    sys.stdout.write(str(n) + '\n')


def select(options, args):
    selection = Selection(args[0])
    source = reader(options, data_path(args[1:]))
    columns = selection.resolve(source.header, source.no_headers)
    output = writer(options)
    if not source.no_headers:
        write_selected(output, source.header, columns)
    for row in source.rows():
        write_selected(output, row, columns)
    output.finish()


def reverse(options, args):
    source = reader(options, data_path(args))
    output = writer(options)
    output.header(source)
    rows = list(source.rows())
    for row in reversed(rows):
        output.write(row)
    output.finish()


def slice_rows(options, args):
    path = data_path(args)
    index = get_index(path)
    source = reader(options, path)
    output = writer(options)
    output.header(source)
    start, end, length, single = [options[k] for k in ('start', 'end', 'len', 'index')]
    if single is not None and any(v is not None for v in (start,end,length)):
        raise ToolError('--index cannot be used with --start, --end or --len')
    if end is not None and length is not None:
        raise ToolError('--end and --len cannot be used at the same time.')
    if single is not None:
        start, length = single, 1
    if start is None:
        start = 0
    if end is not None and end < start:
        raise ToolError('The end of the range ({}) must be greater than or\nequal to the start of the range ({}).'.format(end, start))
    if length is not None:
        end = (start + length) % (1 << 64)
    # Reading is lazy, including when the slice ends before a malformed row.
    if end is None or start < end:
        rows = source.rows()
        if index is not None and start > 0:
            offset_index = start + (0 if source.no_headers else 1)
            if offset_index < len(index[1]):
                source.pos = index[1][offset_index]
                source.record = offset_index
                rows = iter(lambda: source.read(), None)
                base = start
            else:
                base = 0
        else:
            base = 0
        i = base
        while end is None or i < end:
            try:
                row = next(rows)
            except StopIteration:
                break
            if i >= start:
                output.write(row)
            i += 1
    output.finish()


def compare_numbers(a, b):
    _, x = as_number(a)
    _, y = as_number(b)
    if x is None and y is None:
        return 0
    if x is None:
        return -1
    if y is None:
        return 1
    return (x > y) - (x < y)


def sort(options, args):
    source = reader(options, data_path(args))
    columns = select_columns(options, source)
    output = writer(options)
    output.header(source)
    rows = list(source.rows())
    sign = -1 if options['reverse'] else 1
    def compare(a, b):
        for i in columns:
            c = compare_numbers(a[i], b[i]) if options['numeric'] else (a[i] > b[i]) - (a[i] < b[i])
            if c:
                return sign*c
        return 0
    # An insertion pass on short inputs retains the input ordering of equal
    # keys, including incomparables such as floating point NaNs.
    if len(rows) <= 20:
        for i in range(1, len(rows)):
            j = i
            while j and compare(rows[j], rows[j-1]) < 0:
                rows[j], rows[j-1] = rows[j-1], rows[j]
                j -= 1
    else:
        rows.sort(key=functools.cmp_to_key(compare))
    for row in rows:
        output.write(row)
    output.finish()


def search(options, args):
    matches = compile_pattern(args[0], options['ignore-case'])
    source = reader(options, data_path(args[1:]))
    columns = select_columns(options, source)
    output = writer(options)
    output.header(source)
    for row in source.rows():
        found = any(matches(row[i]) for i in columns)
        if found != options['invert-match']:
            output.write(row)
    output.finish()


def format_csv(options, args):
    source = reader(options, data_path(args))
    delimiter = 31 if options['ascii'] else options['out-delimiter']
    terminator = b'\x1e' if options['ascii'] else b'\r\n' if options['crlf'] else b'\n'
    output = writer(options, delimiter=delimiter, terminator=terminator,
                    quote=options['quote'], always=options['quote-always'], escape=options['escape'])
    for row in source.all_rows():
        output.write(row)
    output.finish()


def input_csv(options, args):
    source = reader(options, data_path(args), quote=options['quote'],
                    escape=options['escape'], quoting=not options['no-quoting'])
    output = writer(options)
    for row in source.all_rows():
        output.write(row)
    output.finish()


def fixlengths(options, args):
    path = data_path(args)
    length = options['length']
    if length == 0:
        raise ToolError('Length must be greater than 0.')
    if length is None and path in (None, '-'):
        raise ToolError('<stdin> cannot be used in this command. Please specify a file path.')
    source = reader(options, path, flexible=True)
    rows = source.all_rows()
    if length is None:
        rows = list(rows)
        length = 1
        for row in rows:
            n = len(row)
            while n and not row[n-1]:
                n -= 1
            length = max(length, n)
    output = writer(options)
    for row in rows:
        output.write(row[:length] + [b'']*max(0, length-len(row)))
    output.finish()


def headers(options, args):
    names_only = options['just-names'] or len(args) > 1
    seen = set()
    text = bytearray()
    index = 1
    for path in args or [None]:
        source = reader(options, path)
        for value in source.header:
            if options['intersect'] and value in seen:
                continue
            seen.add(value)
            if not names_only:
                text.extend(str(index).encode() + b'\t')
            text.extend(value + b'\n')
            index += 1
    sys.stdout.buffer.write(elastic_tabs(bytes(text)))


def flatten(options, args):
    source = reader(options, data_path(args))
    labels = source.header
    if source.no_headers:
        labels = [str(i).encode() for i in range(len(labels))]
    separator = options['separator'].encode('utf-8', 'surrogateescape')
    output = bytearray()
    first = True
    try:
        for row in source.rows():
            if not first and separator:
                output.extend(separator + b'\n')
            first = False
            for label, field in zip(labels, row):
                output.extend(label + b'\t' + condense(field, options['condense']) + b'\n')
    finally:
        sys.stdout.buffer.write(elastic_tabs(bytes(output)))


def table(options, args):
    source = reader(options, data_path(args))
    text = bytearray()
    for row in source.all_rows():
        text.extend(csv_record([condense(f, options['condense']) for f in row], delimiter=9))
    stream = open_output(options['output'])
    stream.write(elastic_tabs(bytes(text), options['width'], options['pad']))
    stream.flush()


def frequency(options, args):
    path = data_path(args)
    index = get_index(path)
    source = reader(options, path)
    columns = select_columns(options, source)
    unique = sorted(set(columns))
    counters = [Counter() for _ in unique]
    max_rows = None if index is None else max(0, index[0] - (not source.no_headers))
    for j, row in enumerate(source.rows()):
        if max_rows is not None and j >= max_rows:
            break
        for i, counter in zip(unique, counters):
            value = trim_bytes(row[i])
            if value or not options['no-nulls']:
                counter[value] += 1
    output = writer(options)
    output.write(['field','value','count'])
    for column, counter in zip(columns, counters):
        label = str(column+1).encode() if source.no_headers else source.header[column]
        pairs = sorted(counter.items(), key=lambda kv: kv[1], reverse=not options['asc'])
        if options['limit']:
            pairs = pairs[:options['limit']]
        for value, n in pairs:
            output.write([label, value or b'(NULL)', n])
    output.finish()


def stats(options, args):
    path = data_path(args)
    index = get_index(path)
    source = reader(options, path)
    columns = select_columns(options, source)
    computed = [ColumnStats(options['median'] or options['everything'],
                            options['mode'] or options['everything'],
                            options['cardinality'] or options['everything'],
                            options['nulls']) for _ in columns]
    max_rows = None if index is None else max(0, index[0] - (not source.no_headers))
    for j, row in enumerate(source.rows()):
        if max_rows is not None and j >= max_rows:
            break
        for i, accumulator in zip(columns, computed):
            accumulator.add(row[i])
    output = writer(options)
    names = ['field','type','sum','min','max','min_length','max_length','mean','stddev']
    for extra in ('median','mode','cardinality'):
        if options[extra] or options['everything']:
            names.append(extra)
    output.write(names)
    for i, accumulator in zip(columns, computed):
        label = str(i).encode() if source.no_headers else source.header[i]
        output.write([label] + accumulator.output(options))
    output.finish()


def index_csv(options, args):
    path = args[0]
    if path == '-':
        raise ToolError('Cannot use <stdin> here')
    source = reader(options, path)
    stream = open_output(options['output'] or path + '.idx')
    n = 0
    while True:
        row = source.read()
        if row is None:
            break
        stream.write(struct.pack('>Q', source.last_position[0]))
        n += 1
    stream.write(struct.pack('>Q', n))
    stream.flush()


def cat(options, args):
    mode, paths = args[0], args[1:] or [None]
    output = writer(options)
    if mode == 'rows':
        first = True
        for path in paths:
            source = reader(options, path)
            if first:
                output.header(source)
                first = False
            for row in source.rows():
                output.write(row)
    else:
        sources = [reader(options, path) for path in paths]
        rows = [source.all_rows() for source in sources]
        widths = [len(source.header) for source in sources]
        finished = [False]*len(sources)
        while True:
            combined = []
            any_data = False
            for i, it in enumerate(rows):
                if not finished[i]:
                    try:
                        row = next(it)
                        any_data = True
                    except StopIteration:
                        row = None
                        finished[i] = True
                else:
                    row = None
                if row is None:
                    if not options['pad']:
                        output.finish()
                        return
                    row = [b'']*widths[i]
                combined.extend(row)
            if not any_data:
                break
            output.write(combined)
    output.finish()


def join(options, args):
    if sum(options[k] for k in ('left','right','full','cross')) > 1:
        raise ToolError('Please pick exactly one join operation.')
    c1, p1, c2, p2 = args
    left = reader(options, p1)
    lc = select_columns(options, left, c1)
    right = reader(options, p2)
    rc = select_columns(options, right, c2)
    if len(lc) != len(rc):
        raise ToolError('Column selections must have the same number of columns, but found column selections with {} and {} columns.'.format(len(lc),len(rc)))
    output = writer(options)
    if not options['no-headers']:
        output.write(left.header + right.header)
    def key(row, cols):
        values = [trim_bytes(row[i]) for i in cols]
        if not options['nulls'] and any(not v for v in values):
            return None
        if options['no-case']:
            values = [v.decode('utf-8','surrogateescape').lower().encode('utf-8','surrogateescape') for v in values]
        return tuple(values)
    left_empty = [b'']*len(left.header)
    right_empty = [b'']*len(right.header)
    if options['right']:
        rows = list(left.rows())
        lookup = defaultdict(list)
        for row in rows:
            k = key(row, lc)
            if k is not None:
                lookup[k].append(row)
        for row in right.rows():
            matches = lookup.get(key(row, rc), [])
            for other in matches or [left_empty]:
                output.write(other + row)
    else:
        rows = list(right.rows())
        lookup = defaultdict(list)
        for i, row in enumerate(rows):
            k = key(row, rc)
            if k is not None:
                lookup[k].append((i,row))
        used = set()
        for row in left.rows():
            matches = list(enumerate(rows)) if options['cross'] else lookup.get(key(row,lc), [])
            for i, other in matches:
                output.write(row + other)
                used.add(i)
            if not matches and (options['left'] or options['full']):
                output.write(row + right_empty)
        if options['full']:
            for i, row in enumerate(rows):
                if i not in used:
                    output.write(left_empty + row)
    output.finish()


def filename_template(options):
    template = options['filename']
    if template.count('{}') != 1:
        raise ToolError("The --filename argument must contain one '{}'.")
    return template


def split(options, args):
    size = options['size']
    if not size:
        raise ToolError('--size must be greater than 0.')
    template = filename_template(options)
    outdir = args[0]
    path = data_path(args[1:])
    get_index(path)
    source = reader(options, path)
    make_directory(outdir)
    def new_output(n):
        w = Writer(os.path.join(outdir, template.replace('{}',str(n))))
        if not source.no_headers:
            w.write(source.header)
        return w
    output = new_output(0)
    for i, row in enumerate(source.rows()):
        if i and i % size == 0:
            output.finish()
            output = new_output(i)
        output.write(row)
    output.finish()


def partition(options, args):
    template = filename_template(options)
    column, outdir = args[:2]
    source = reader(options, data_path(args[2:]))
    columns = select_columns(options, source, column)
    if len(columns) != 1:
        raise ToolError('can only partition on one column')
    col = columns[0]
    make_directory(outdir)
    writers = {}
    used = set()
    collision = 0
    def field_name(value):
        s = value.decode('utf-8','replace')
        return ''.join(c for c in s if c.isalnum() or c == '_') or 'empty'
    def dropped(row):
        return row[:col] + row[col+1:] if options['drop'] else row
    for row in source.rows():
        key = row[col]
        if options['prefix-length'] is not None:
            key = key[:options['prefix-length']]
        if key not in writers:
            base = name = field_name(key)
            while name in used:
                collision += 1
                name = base + '_' + str(collision)
            used.add(name)
            w = Writer(os.path.join(outdir, template.replace('{}',name)))
            if not source.no_headers:
                w.write(dropped(source.header))
            writers[key] = w
        writers[key].write(dropped(row))
    for w in writers.values():
        w.finish()


def sample(options, args):
    size = args[0]
    path = data_path(args[1:])
    get_index(path)
    source = reader(options, path)
    output = writer(options)
    output.header(source)
    from .sampling import RandomSource
    rng = RandomSource(options['seed'])
    reservoir = []
    for i, row in enumerate(source.rows()):
        if i < size:
            reservoir.append(row)
        else:
            j = rng.below(i+1)
            if j < size:
                reservoir[j] = row
    for row in reservoir:
        output.write(row)
    output.finish()


COMMAND_FUNCTIONS = {
    'count': count, 'select': select, 'reverse': reverse, 'slice': slice_rows,
    'sort': sort, 'search': search, 'fmt': format_csv, 'input': input_csv,
    'fixlengths': fixlengths, 'headers': headers, 'flatten': flatten,
    'table': table, 'frequency': frequency, 'stats': stats, 'index': index_csv,
    'cat': cat, 'join': join, 'split': split, 'partition': partition, 'sample': sample,
