 for x in a:
  n+=1;d=x-m;m+=d/n;q=((n-1)*q+d*(x-m))/n
 return n,m,q

def calc(a,j,means,vars,ch,initial=0):
 k=max(len(a)//j,1) if ch==0 else (len(a)+j-1)//j
 chunks=[accum(a[i:i+k]) for i in range(0,len(a),k)]
 n,m,q=chunks[0] if initial==0 else (0,0.,0.)
